css:
.mktg-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #0f0c29 0%, #302b63 50%, #24243e 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    color: #e0e0e0;
}

.mktg-sim-container .mktg-sim-header {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 24px;
    box-shadow: 0 8px 32px rgba(102, 126, 234, 0.3);
    text-align: center;
}

.mktg-sim-container .mktg-sim-header h1 {
    font-size: 1.8rem;
    font-weight: 800;
    margin-bottom: 5px;
}

.mktg-sim-container .mktg-sim-header p {
    opacity: 0.9;
    font-size: 1rem;
    margin: 0;
}

.mktg-sim-container .mktg-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    margin-bottom: 20px;
    color: #b0b0cc;
}

.mktg-sim-container .mktg-sim-period-counter span {
    margin: 0 3px;
}

.mktg-sim-container .mktg-sim-briefing {
    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
    border-left: 4px solid #667eea;
    border-radius: 12px;
    padding: 20px 24px;
    margin-bottom: 24px;
    position: relative;
}

.mktg-sim-container .mktg-sim-briefing-badge {
    display: inline-block;
    background: #667eea;
    color: white;
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 3px 10px;
    border-radius: 20px;
    margin-bottom: 8px;
    letter-spacing: 0.5px;
}

.mktg-sim-container .mktg-sim-briefing h3 {
    color: #ffffff;
    font-size: 1.15rem;
    margin-bottom: 8px;
}

.mktg-sim-container .mktg-sim-briefing p {
    color: #b0b0cc;
    font-size: 0.92rem;
    line-height: 1.6;
    margin: 0;
}

.mktg-sim-container .mktg-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-bottom: 24px;
}

.mktg-sim-container .mktg-sim-status-card {
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 18px 16px;
    text-align: center;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    backdrop-filter: blur(10px);
}

.mktg-sim-container .mktg-sim-status-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 24px rgba(0,0,0,0.3);
}

.mktg-sim-container .mktg-sim-label {
    color: #8888aa;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    margin-bottom: 6px;
}

.mktg-sim-container .mktg-sim-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #ffffff;
}

.mktg-sim-container .mktg-sim-card-revenue .mktg-sim-value { color: #2ecc71; }
.mktg-sim-container .mktg-sim-card-roas .mktg-sim-value { color: #3498db; }
.mktg-sim-container .mktg-sim-card-cac .mktg-sim-value { color: #e67e22; }
.mktg-sim-container .mktg-sim-card-awareness .mktg-sim-value { color: #9b59b6; }
.mktg-sim-container .mktg-sim-card-conversion .mktg-sim-value { color: #1abc9c; }
.mktg-sim-container .mktg-sim-card-customers .mktg-sim-value { color: #f1c40f; }

.mktg-sim-container .mktg-sim-controls {
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 24px;
}

.mktg-sim-container .mktg-sim-controls h3 {
    color: #ffffff;
    font-size: 1.15rem;
    margin-bottom: 12px;
}

.mktg-sim-container .mktg-sim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: rgba(102, 126, 234, 0.12);
    border-radius: 10px;
    padding: 10px 16px;
    margin-bottom: 20px;
    font-size: 0.88rem;
    color: #b0b0cc;
    flex-wrap: wrap;
    gap: 8px;
}

.mktg-sim-container .mktg-sim-budget-tracker strong {
    color: #ffffff;
}

.mktg-sim-container .mktg-sim-channel-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 14px;
    margin-bottom: 20px;
}

.mktg-sim-container .mktg-sim-channel-input {
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 12px;
    padding: 14px;
    transition: border-color 0.3s ease;
}

.mktg-sim-container .mktg-sim-channel-input:hover {
    border-color: rgba(102, 126, 234, 0.4);
}

.mktg-sim-container .mktg-sim-channel-input label {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 0.82rem;
    color: #b0b0cc;
    margin-bottom: 8px;
    font-weight: 600;
}

.mktg-sim-container .mktg-sim-channel-icon {
    font-size: 1.1rem;
}

.mktg-sim-container .mktg-sim-channel-input input {
    width: 100%;
    padding: 8px 12px;
    border: 1px solid rgba(255,255,255,0.15);
    border-radius: 8px;
    background: rgba(0,0,0,0.3);
    color: #ffffff;
    font-size: 1rem;
    font-weight: 600;
    text-align: right;
}

.mktg-sim-container .mktg-sim-channel-input input:focus {
    outline: none;
    border-color: #667eea;
    box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.2);
}

.mktg-sim-container .mktg-sim-actions {
    display: flex;
    gap: 12px;
    align-items: center;
}

.mktg-sim-container .mktg-sim-actions .btn-primary {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    border: none;
    padding: 12px 36px;
    font-weight: 700;
    border-radius: 10px;
    font-size: 1rem;
    letter-spacing: 0.3px;
}

.mktg-sim-container .mktg-sim-actions .btn-primary:hover {
    box-shadow: 0 4px 20px rgba(102, 126, 234, 0.4);
    transform: translateY(-1px);
}

.mktg-sim-container .mktg-sim-actions .btn-outline-secondary {
    color: #8888aa;
    border-color: rgba(255,255,255,0.15);
}

.mktg-sim-container .mktg-sim-history {
    margin-bottom: 24px;
}

.mktg-sim-container .mktg-sim-history .table {
    background: rgba(255,255,255,0.04);
    color: #e0e0e0;
    border-radius: 12px;
    overflow: hidden;
}

.mktg-sim-container .mktg-sim-history .table th {
    background: rgba(102, 126, 234, 0.15);
    color: #b0b0cc;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    border: none;
    padding: 10px 12px;
}

.mktg-sim-container .mktg-sim-history .table td {
    border-color: rgba(255,255,255,0.05);
    padding: 8px 12px;
    font-size: 0.88rem;
}

.mktg-sim-container .mktg-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 20px;
}

.mktg-sim-container .mktg-sim-chart-wrapper {
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 20px;
    min-height: 280px;
}

@media (max-width: 992px) {
    .mktg-sim-container .mktg-sim-channel-grid {
        grid-template-columns: repeat(2, 1fr);
    }
    .mktg-sim-container .mktg-sim-charts {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 576px) {
    .mktg-sim-container .mktg-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .mktg-sim-container .mktg-sim-channel-grid {
        grid-template-columns: 1fr;
    }
    .mktg-sim-container .mktg-sim-budget-bar {
        flex-direction: column;
        text-align: center;
    }
}

/* EQIL 2026-10-29: contribution card and debrief (append-only, namespaced) */
.mktg-sim-container .mktg-sim-card-contribution { grid-column: 1 / -1; }
.mktg-sim-container .mktg-sim-card-contribution .mktg-sim-value { color: #7ee2b8; }
.mktg-sim-cm { text-align: left; color: #1f2937; line-height: 1.5; }
.mktg-sim-cm-head { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; margin-bottom: 8px; }
.mktg-sim-cm-score { font-size: 1.1rem; font-weight: 600; }
.mktg-sim-cm-num { font-size: 2.4rem; font-weight: 800; }
.mktg-sim-cm-tier { padding: 4px 12px; border-radius: 999px; font-weight: 700; background: #e5e7eb; color: #111827; }
.mktg-sim-cm-tier-excellent { background: #d1fae5; color: #065f46; }
.mktg-sim-cm-tier-strong { background: #dbeafe; color: #1e3a8a; }
.mktg-sim-cm-tier-competent { background: #fef3c7; color: #78350f; }
.mktg-sim-cm-tier-needs_improvement { background: #fee2e2; color: #7f1d1d; }
.mktg-sim-cm-basis { font-size: 0.88rem; color: #374151; }
.mktg-sim-cm-kpis { list-style: none; padding: 0; margin: 8px 0 12px; display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 8px; }
.mktg-sim-cm-kpis li { background: #f3f4f6; border-radius: 8px; padding: 8px 10px; display: flex; flex-direction: column; }
.mktg-sim-cm-k { font-size: 0.75rem; color: #4b5563; }
.mktg-sim-cm-v { font-size: 1.05rem; font-weight: 700; color: #111827; }
.mktg-sim-cm-h { font-size: 1rem; font-weight: 700; margin: 12px 0 4px; color: #111827; }
.mktg-sim-cm-tp { background: #eef2ff; border-left: 4px solid #4f46e5; padding: 8px 12px; border-radius: 6px; color: #1f2937; }
.mktg-sim-cm-list { padding-left: 20px; margin: 0; }

/* EQIL 2026-10-29: accessibility (append-only, namespaced) */
.mktg-sim-container .mktg-sim-sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.mktg-sim-container input:focus-visible, .mktg-sim-container button:focus-visible { outline: 3px solid #ffd166; outline-offset: 2px; }
.mktg-sim-container input[type=number] { color-scheme: dark; }
@media (prefers-reduced-motion: reduce) {
    .mktg-sim-container *, .mktg-sim-container *::before, .mktg-sim-container *::after { transition: none !important; animation: none !important; }
    .mktg-sim-container .mktg-sim-status-card:hover { transform: none; }
}

