        getPresets() { return null; }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var self = this;
            var totalRevenue = 0, totalSpend = 0, totalCustomers = 0, finalAwareness = 30, convSum = 0;
            var weeks = [];
            for (var i = 0; i < history.length; i++) {
                var r = history[i].results || {};
                var dd = history[i].decisions || {};
                totalRevenue += r.revenue || 0;
                totalSpend += r.spend || 0;
                totalCustomers += r.newCustomers || 0;
                finalAwareness = r.brandAwareness || finalAwareness;
                convSum += r.conversionRate || 0;
                weeks.push({ sem: +dd.sem || 0, social: +dd.social || 0, email: +dd.email || 0, seo: +dd.seo || 0,
                    influencer: +dd.influencer || 0, display: +dd.display || 0, spend: r.spend || 0 });
            }
            var last = history[history.length - 1].results || {};
            var blendedROAS = totalSpend > 0 ? Math.round(totalRevenue / totalSpend * 100) / 100 : 0;
            var avgCAC = totalCustomers > 0 ? Math.round(totalSpend / totalCustomers) : 0;
            var avgConv = Math.round(convSum / history.length * 10) / 10;
            var expC = (typeof last.expectedContribution === 'number') ? last.expectedContribution : Math.round(this.MARGIN * totalRevenue - totalSpend);
            var bookedC = Math.round(this.MARGIN * totalRevenue - totalSpend);
            var score = this._composite(expC);
            var tier = this._tier(score);
            var labelKey = { excellent: 'tier_excellent', strong: 'tier_strong', competent: 'tier_competent', needs_improvement: 'tier_needs_improvement' }[tier];

            // what this run did, read from its own history (EQIL §14 item 13: never describe a play not made)
            var w = function(k) { return weeks[k] || { sem: 0, social: 0, email: 0, seo: 0, influencer: 0, display: 0, spend: 0 }; };
            var early = w(0).spend + w(1).spend, earlySeo = w(0).seo + w(1).seo;
            var lateSeo = w(2).seo + w(3).seo;
            var upper = 0, over = 0;
            weeks.forEach(function(x) {
                upper += x.influencer + x.display;
                for (var k in self.KINKS) { over += Math.max(0, x[k] - self.KINKS[k]); }
            });
            var wasted = last.emailWasted || 0;
            var found = [];
            if (totalSpend > 0 && upper / totalSpend >= 0.35) found.push({ id: 'brand', text: this._tt('tp_brand', { pct: Math.round(100 * upper / totalSpend), aw: Math.round(finalAwareness) }) });
            if (w(1).sem > this.KINKS.sem) found.push({ id: 'defend', text: this._tt('tp_defend', { sem: this._money(w(1).sem) }) });
            if (wasted > 10000) found.push({ id: 'email', text: this._tt('tp_email', { waste: this._money(wasted) }) });
            if (early > 0 && earlySeo / early < 0.25) found.push({ id: 'starved', text: this._tt('tp_starved', { pct: Math.round(100 * earlySeo / early) }) });
            if (history.length >= 3 && lateSeo > 10000) found.push({ id: 'lateseo', text: this._tt('tp_lateseo', { seo: this._money(lateSeo) }) });

            var turningPoint;
            if (found.length) turningPoint = found[0].text;
            else if (early > 0 && earlySeo / early >= 0.5) turningPoint = this._tt('tp_good_early');
            else turningPoint = this._tt('tp_none');

            var insights = [];
            for (var f = 1; f < found.length; f++) insights.push(found[f].text);
            if (over > 25000) insights.push(this._tt('ins_saturation', { over: this._money(over) }));
            if ((last.lagRevenue || 0) > 50000) insights.push(this._tt('ins_lag', { lag: this._money(last.lagRevenue) }));
            var unspent = this.WEEKLY_BUDGET * history.length - totalSpend;
            if (unspent >= 25000) insights.push(this._tt('ins_unspent', { u: this._money(unspent) }));
            insights.push(this._tt('ins_roas', { roas: blendedROAS.toFixed(2), spend: this._money(totalSpend) }));
            insights.push(this._tt('ins_noise', { n: this._money(Math.abs(totalRevenue - (last.expectedRevenue || totalRevenue))) }));
            insights = insights.slice(0, 5);

            return {
                totalRevenue: totalRevenue,
                totalSpend: totalSpend,
                blendedROAS: blendedROAS,
                totalCustomers: totalCustomers,
                avgCAC: avgCAC,
                finalAwareness: Math.round(finalAwareness),
                avgConversion: avgConv,
                contribution: bookedC,
                expectedContribution: expC,
                score: score,
                overallScore: score,
                totalScore: score,
                composite: score,
                performance: tier,
                performanceKey: labelKey,
                performanceLabel: this._tt(labelKey),
                turningPoint: turningPoint,
                mistakes: found.map(function(x) { return x.id; }),
                insights: insights,
                questions: [this._tt('q1'), this._tt('q2'), this._tt('q3')]
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var self = this;
            var esc = function(v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
            var kpi = function(k, v) { return '<li><span class="mktg-sim-cm-k">' + esc(self._tt(k)) + '</span><span class="mktg-sim-cm-v">' + esc(v) + '</span></li>'; };
            var li = function(arr) { return (arr || []).map(function(x) { return '<li>' + esc(x) + '</li>'; }).join(''); };
            return '<div class="mktg-sim-cm">' +
